/* generated at build time: every page, session, announcement and article, for the command palette */
window.U26_INDEX=[{"t":"page","title":"Home","sub":"Key numbers, the big picture, and a way into each page","url":"./"},{"t":"page","title":"Sessions","sub":"13 sessions worth your time, ranked and filterable","url":"sessions.html"},{"t":"page","title":"Announcements","sub":"Every announcement by topic with status and docs links","url":"announcements.html"},{"t":"page","title":"Outside voices","sub":"What press, analysts and the community said","url":"voices.html"},{"t":"session","title":"Stop waiting on your own pull requests: stacked PRs in practice","sub":"Sameen Karim · GitHub · SDLC","desc":"Break a change into small dependent PRs, review each on its own, merge as each is ready. Live demo with the GitHub CLI; a workflow you can use tomorrow.","url":"sessions.html#s1","st":"Top pick","sc":"preview"},{"t":"session","title":"Inside GitHub Copilot's coding harness: optimizing across every model","sub":"Julia Kasper · Microsoft · Agentic AI","desc":"How the Copilot team tests and tunes its agent across models: reproducible benchmarks, thousands of autonomous tasks, LLM-graded assertions.","url":"sessions.html#s2","st":"Top pick","sc":"preview"},{"t":"session","title":"How GitHub taught Copilot to remember, and when to forget","sub":"Cooper Nederhood, Alejandro Carderera · GitHub · Agentic AI","desc":"A benchmark built from real PR sequences shows that piling up context can hurt agent performance, and what that means for agent memory.","url":"sessions.html#s3","st":"Top pick","sc":"preview"},{"t":"session","title":"Disrupting supply chain attacks: a threat framework for GitHub Actions","sub":"Steve Glass, Greg Ose · GitHub · Security","desc":"Maps supply chain attack techniques to Actions controls across the ecosystem, the workflow attack surface and runner infrastructure.","url":"sessions.html#s4","st":"Top pick","sc":"preview"},{"t":"session","title":"What happens behind the scenes when you run npm install","sub":"Karen Li, Leo Balter · GitHub · Security","desc":"Traces a dependency back to the people, permissions and release systems behind it, including the limits of npm audit , provenance and OIDC.","url":"sessions.html#s5","st":"Top pick","sc":"preview"},{"t":"session","title":"Treat your AI context as infrastructure","sub":"Christopher Harrison · GitHub · Agentic AI","desc":"What instructions, skills and MCP servers are each best for, and how to share the right context across a team as the setup grows.","url":"sessions.html#s6"},{"t":"session","title":"Your benchmark is lying: what evals actually look like","sub":"Walker Chabbott · GitHub · Julia Kasper · Microsoft · Agentic AI","desc":"How Copilot evaluates models in production: what the team measures, and what it has stopped measuring.","url":"sessions.html#s7"},{"t":"session","title":"Beyond pass or fail: how agents verify AI-generated code","sub":"Jeff An · Momentic · SDLC","desc":"How agents investigate an app, reproduce odd behavior, and tell a product bug from a broken test or infrastructure failure, with deterministic controls around them.","url":"sessions.html#s8"},{"t":"session","title":"The 2 a.m. RCA agent: architecting AI that investigates, not hallucinates","sub":"Achin Gupta · Intuit · Divya Mahajan · Amazon · SDLC","desc":"Deterministic code collects signals, traverses topology, correlates and scores. The language model only narrates the evidence.","url":"sessions.html#s9"},{"t":"session","title":"Open pull requests, don't merge them: fine-grained authorization for hosted MCP servers","sub":"Nick Taylor · Pomerium · Security","desc":"An identity-aware proxy enforces per-identity permissions in front of a hosted MCP server, with no changes to the upstream server.","url":"sessions.html#s10"},{"t":"session","title":"Build once, run on any agent: a practical guide to agent skills","sub":"Andrea Griffiths · GitHub · Shishir Tewari · Procore · Agentic AI","desc":"When a workflow is worth turning into a reusable skill, with examples from recurring work and a production data engineering team.","url":"sessions.html#s11"},{"t":"session","title":"One CLI to replace your entire JavaScript toolchain","sub":"Alexander Lichter · VoidZero · SDLC","desc":"A real migration to Vite+, an open source CLI for bundling, testing, linting, formatting and runtime management, plus the roadmap.","url":"sessions.html#s12"},{"t":"session","title":"Lessons from building tech in a low-connectivity community","sub":"Alex Junior Antwi · Braveon AI · Community","desc":"Building CarbonSight for low-connectivity communities in Ghana, with an offline demo.","url":"sessions.html#s13"},{"t":"announcement","title":"GitHub Copilot app","sub":"Copilot & agents #1","desc":"An app for agent-driven delivery. Links your agents and tools across projects and covers non-code work like specs, design discussions and telemetry analysis. The docs give no GA or preview label for the app itself.","url":"announcements.html#a1","st":"Available","sc":"live"},{"t":"announcement","title":"Copilot Fusion","sub":"Copilot & agents #2","desc":"Formerly Project HydraFusion. Pick Standard, High or Max effort; Fusion decides whether one model or several fits. Works in VS Code, Copilot CLI, the Copilot app and JetBrains. Standard is on every plan; High and Max need Pro+, Max, Business or Enterprise. No separate charge: you pay each model's standard rate, with 30% off model costs on paid plans through Nov 30, 2026. It runs tasks as a single model, a cascade (a lighter model drafts, a quality check escalates) or a critique (one drafts, another reviews). GitHub says Fusion Max came within two points of Opus 5.5 Max on the Artificial Analysis Coding Agent Index at half the cost and 40% less time. Artificial Analysis's own figures, per VentureBeat: $5.59 per task versus $11.42, index score 60 versus about 62. The time saving is GitHub-reported.","url":"announcements.html#a2","st":"GA","sc":"ga"},{"t":"announcement","title":"Copilot Projects","sub":"Copilot & agents #3","desc":"A shared workspace for goals that span repos, or no repo at all. Runs parallel agent sessions in the background and returns results like PRs for review.","url":"announcements.html#a3","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Session continuity","sub":"Copilot & agents #4","desc":"Start and follow one cloud agent session across the Copilot app, VS Code, the CLI, GitHub Mobile and the web, and continue sessions begun in Slack or Teams DMs. The agent keeps running in the cloud.","url":"announcements.html#a4","st":"Announced","sc":""},{"t":"announcement","title":"Copilot automations","sub":"Copilot & agents #5","desc":"Cloud-run workflows in a repo, started manually, by an event or on a schedule (issue triage, code review). They watch signals like whether people change the labels they apply or accept their review comments, then propose edits to their own prompts, tools or triggers; nothing changes until you accept. Pro through Enterprise plans, private and internal repos only; each run uses AI credits and Actions minutes.","url":"announcements.html#a5","st":"Available","sc":"live"},{"t":"announcement","title":"Copilot connectors","sub":"Copilot & agents #6","desc":"Authenticate once with services like Vercel, Cloudflare and Sentry. GitHub manages the MCP connection across the Copilot app, CLI, VS Code, web and code review. GitHub also names Cloudflare, Datadog and Figma as ecosystem partners.","url":"announcements.html#a6","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Computer use","sub":"Copilot & agents #7","desc":"Copilot operates desktop apps that have no API, CLI or MCP support. Asks for approval first; organizations can disable it. macOS and Windows.","url":"announcements.html#a7","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Fusion with local models","sub":"Copilot & agents #8","desc":"Opt-in experimental routing between local and cloud models in the CLI, Copilot app and VS Code, using MAI Code 1.1 Flash on Windows ML or a bring-your-own model such as Qwen3.8 Flash Next. Routing decisions are still made in the cloud, so sessions are not offline.","url":"announcements.html#a8","st":"Experimental preview","sc":"preview"},{"t":"announcement","title":"Connected tools and image generation","sub":"Copilot & agents #9","desc":"In the Copilot app, use context from tools like Slack and Figma to research requests, draft specs or work on designs. Create and edit images from chat.","url":"announcements.html#a9","st":"Announced","sc":""},{"t":"announcement","title":"Copilot code review Max","sub":"Review & workflow #10","desc":"The highest-effort review tier. Several independent review agents on models from different providers run, then an aggregation agent reconciles their findings into one review. GitHub says it posted the top F1 score on ReviewBench for high-severity issues. Docs put the average at about $10 per review (typically $1.50 to $25). Set it per PR, or as a default with an admin cap. Lite and Balanced remain for everyday reviews.","url":"announcements.html#a10","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Copilot approvals","sub":"Review & workflow #11","desc":"Copilot can approve a PR, and its approval counts toward required approvals. Off by default; admins enable it at enterprise, organization or repo level, and repo admins can limit which file paths Copilot may approve. Like a human approval, it is dismissed when new commits are pushed. Pro through Enterprise plans.","url":"announcements.html#a11","st":"GA","sc":"ga"},{"t":"announcement","title":"Stacked pull requests","sub":"Review & workflow #12","desc":"Split large work into small, linked PRs, review each on its own, then merge the whole stack in one click. Start with the gh stack extension for GitHub CLI.","url":"announcements.html#a12","st":"Available","sc":"live"},{"t":"announcement","title":"Pull request inbox","sub":"Review & workflow #13","desc":"Scan open work, see its status and jump to the PRs that need you.","url":"announcements.html#a13","st":"Available","sc":"live"},{"t":"announcement","title":"Issue artifacts","sub":"Review & workflow #14","desc":"Attach plans, research and links to an issue so teammates see the reasoning behind the work. CLI commands need GitHub CLI 2.103.0 or later.","url":"announcements.html#a14","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Attach media from GitHub CLI","sub":"Review & workflow #15","desc":"A repeatable --attach flag embeds images and videos in issues, PRs and comments from your terminal.","url":"announcements.html#a15","st":"Available","sc":"live"},{"t":"announcement","title":"Agent Host and phone control","sub":"In your editor #16","desc":"In VS Code, agent sessions run independently of editor windows, or on a remote machine over SSH or dev tunnels. GitHub Mobile can monitor, steer or start tasks on your dev machine. An open Agent Host Protocol lets you build your own client (libraries for TypeScript, Rust, Go, Kotlin and Swift).","url":"announcements.html#a16","st":"Announced","sc":""},{"t":"announcement","title":"Copilot harness is the default","sub":"In your editor #17","desc":"The Microsoft Copilot harness, built on the Copilot SDK, is now the default for new sessions in VS Code and JetBrains, aiming for consistent behavior across the editor, CLI and Copilot app.","url":"announcements.html#a17","st":"Available","sc":"live"},{"t":"announcement","title":"Compare model results","sub":"In your editor #18","desc":"Run models and harnesses in parallel in VS Code and view results side by side. A Judge model can recommend one, and Synthesize merges ideas from several.","url":"announcements.html#a18","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Marketplace customizations and plugin controls","sub":"In your editor #19","desc":"A Browse page for skills, MCP servers and plugins, enabled by default in preview. Business and Enterprise admins can require or block plugins, add marketplaces and limit installs to approved sources. Connectors (Slack, Notion and Microsoft Learn context) are also in preview on all plans.","url":"announcements.html#a19","st":"Public preview","sc":"preview"},{"t":"announcement","title":"JetBrains: local sandboxes and next edit suggestions","sub":"In your editor #20","desc":"Local sandboxes (Copilot-launched tools run on your machine with limited file, network and credential access) and next edit suggestions are generally available in JetBrains IDEs. Fusion is rolling out there too, replacing the Auto option.","url":"announcements.html#a20","st":"GA","sc":"ga"},{"t":"announcement","title":"Security extension for the Copilot app","sub":"Security #21","desc":"A Security canvas shows code you and your agents just wrote next to code scanning alerts. Ask Copilot to explain and fix findings, then review each change. Code scanning alerts only (not Dependabot or secret scanning), and fixes stay local until you commit.","url":"announcements.html#a21","st":"Public preview","sc":"preview"},{"t":"announcement","title":"AI Scan","sub":"Security #22","desc":"On-demand whole-repo scanning in any language, with findings you can assign to Copilot. Also checks PRs in languages CodeQL doesn't cover, such as PHP and Terraform. The public preview status is stated for repository scanning.","url":"announcements.html#a22","st":"Public preview","sc":"preview"},{"t":"announcement","title":"AI push protection","sub":"Security #23","desc":"Catches unstructured secrets like passwords that patterns miss and blocks them at push, whether a person or an agent wrote the code. Needs push protection and AI secret detection both on, plus Secret Protection or Advanced Security. Uses AI credits.","url":"announcements.html#a23","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Package firewall","sub":"Security #24","desc":"Stops malicious and risky npm packages before agents, runners or IDEs install them. npm only for now; Artifactory support is experimental.","url":"announcements.html#a24","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Reachability analysis","sub":"Security #25","desc":"Shows which vulnerable functions your JavaScript or TypeScript code actually calls, so you can prioritize Dependabot alerts. Needs a lock file and GitHub-hosted runners.","url":"announcements.html#a25","st":"Public preview","sc":"preview"},{"t":"announcement","title":"Capacity added this year","sub":"Infrastructure #26","desc":"4 million CPU cores, 160 PB of high-speed storage and 50 Tb/s of network capacity.","url":"announcements.html#a26","st":"Done","sc":"live"},{"t":"announcement","title":"New Git architecture","sub":"Infrastructure #27","desc":"GitHub calls it its future architecture and is building it while the service keeps running: simpler primitives, storage decoupled from compute, minimal coordination, with authoritative data in Azure Blob Storage. In internal benchmarks it delivered up to 35× higher write throughput. No rollout dates given.","url":"announcements.html#a27","st":"In progress","sc":"prog"},{"t":"announcement","title":"Multi-region deployment in Azure","sub":"Infrastructure #28","desc":"Migration in progress; GitHub expects to finish early next year. As of Oct 21, a copy of 99.99999% of repositories is in Azure and Azure serves about half of Git traffic. The busiest repos are held back by a roughly 25 ms round trip.","url":"announcements.html#a28","st":"In progress","sc":"prog"},{"t":"announcement","title":"Copilot included with GitHub Enterprise","sub":"Plans #29","desc":"Enterprise customers get all Copilot features (app, code review, automations) without a separate subscription and pay for the AI credits they use. Available now through GitHub Sales; self-serve is coming. Existing Copilot Business and Enterprise plans can stay as they are.","url":"announcements.html#a29","st":"Available","sc":"live"},{"t":"announcement","title":"Octoverse 2026","sub":"Reports & what's next #30","desc":"For the 12 months to Sept 30: 17.9B pushes, 34.3B commits, 1.3B merged PRs, 225M+ developers. TypeScript is #1, then Python and JavaScript. Over 40% of PRs in September began with an agent's first draft. Copilot cloud agent usage grew 230% year over year. Read the post .","url":"announcements.html#a30","st":"Published","sc":"live"},{"t":"announcement","title":"Universe '27 and Universe on the road","sub":"Reports & what's next #31","desc":"Next Universe is planned for October 2027. Local “on the road” events are coming to other cities.","url":"announcements.html#a31","st":"Announced","sc":""},{"t":"voice","title":"GitHub powering up four million extra cores to stop its service going down","sub":"Thomas Claburn · The Register · Oct 28","desc":"Frames the build-out against a year of outages: 7.4B commits in September (five times a year earlier), trouble from last December, and 90-day availability that touched about 84% on May 7, per reconstructed status-page data. Skeptical Says the surge “caught the company unprepared” and reads free Copilot seats for Enterprise as an effort to boost workplace usage. Performance claims are attributed to GitHub executives.","url":"voices.html#v1"},{"t":"voice","title":"GitHub Copilot Fusion mixes models to achieve near-Opus 5.5 coding performance at half the per-task cost","sub":"Carl Franzen · VentureBeat · Oct 28","desc":"Reports Artificial Analysis's measurements of Fusion Max: $5.59 per task versus $11.42 for Claude Code on Opus 5.5 Max, an index score of 60 against roughly 62, using about half the tokens. Independent data, with caveats Results were uneven (Fusion led Terminal-Bench 4.0 but trailed on FrontierCode). The 40% time saving is GitHub-reported, and benchmark costs are not a forecast of an enterprise bill.","url":"voices.html#v2"},{"t":"voice","title":"GitHub launches Copilot Fusion as agents start 40% of pull requests","sub":"Ana Maria Constantin · The Next Web · Oct 28","desc":"Covers Fusion, Enterprise billing, Octoverse and the infrastructure build-out, and points out that nearly every performance and cost figure comes from Microsoft and GitHub executives. Read the numbers carefully Parikh's “half the cost” and Nadella's “up to 77%” may measure different things, and “started with an agent draft” says nothing about whether the code was kept. GitHub says its agent count is a floor.","url":"voices.html#v3"},{"t":"voice","title":"GitHub bets on multi-agent software development with Copilot overhaul","sub":"Anirban Ghoshal · InfoWorld · Oct 30","desc":"Quotes three analysts on the redesigned Copilot app and Projects. The upside is one governed platform and less tool sprawl; the risks are agents colliding on the same files and ten parallel sessions producing ten PRs to review. Governance first Advice to CIOs: restrict agent access to specific repos, enforce branch protection, require human approval before agent PRs merge, and send agent audit logs to a SIEM. Cites a 2026 study (CooperBench) finding about 30% lower success when agents collaborate.","url":"voices.html#v4"},{"t":"voice","title":"Does the World Need a New GitHub?","sub":"Kanishk Singh · Analytics India Magazine · Nov 3","desc":"Sets GitHub's rebuild beside the year's reliability record (eight incidents in July, a nearly eight-hour outage in August) and names rivals including Entire and Cursor Origin. Reliability and rivals Asked directly, GitHub COO Kyle Daigle says “I don't think the world needs a new GitHub.” The piece also quotes Parikh conceding “there are times this year when we struggled.”","url":"voices.html#v5"},{"t":"voice","title":"Can Microsoft's Copilot Charge Enough for Its Heaviest Users?","sub":"Kiara Taylor · Investing.com · Nov 9","desc":"Asks whether Microsoft can profitably bill Copilot's heaviest users now that usage-based credits exist, using Copilot Business's $19 seat with 1,900 pooled credits as the worked example. Follow the margin Finds Microsoft's disclosures do not separate paid overage from included or promotional credits, and that GitHub appears in 13 sentences of the earnings call with no cost or margin figures.","url":"voices.html#v6"},{"t":"voice","title":"GitHub Is Processing 17 Million AI Pull Requests a Month. Can a Platform Built in 2008 Actually Handle That?","sub":"Ronald Holman · Tech Times · Oct 28","desc":"Reports that GitHub's former CEO Thomas Dohmke launched a rival platform, Entire, days before Universe, billed as a distributed Git forge for agent-era workloads. Entire is also mentioned by Analytics India Magazine and The AI Economy. Competition Sets Universe's infrastructure message against that launch. The $60M funding figure is Tech Times' own, and its 17 million PRs a month headline figure could not be matched to Octoverse.","url":"voices.html#v7"},{"t":"voice","title":"Human judgment is the scarce resource in AI software development says GitHub CTO","sub":"Vladimir Fedorov · iTWire · Oct 29 · GitHub's CTO","desc":"An interview at Universe on where humans belong as agents write and review code. An interview with a GitHub executive, so GitHub's view rather than an outside check. The case for approvals Fedorov points to models from different families catching each other's mistakes, the idea behind Max review. Copilot approvals are off by default and admins can restrict which file paths Copilot may approve.","url":"voices.html#v8"},{"t":"voice","title":"GitHub’s Growth: 225M Developers, 34.3B Commits — Jay Parikh, EVP of CoreAI, Microsoft","sub":"Jay Parikh · Latent Space · Nov 8 · summary via BigGo","desc":"A video interview recorded after the keynote. Per BigGo's summary, Parikh describes GitHub as composable primitives (repos, issues, PRs, security findings) rather than one enforced workflow, and says PRs can become optional. On cost and reliability Per the summary, GitHub is adding per-organization token-spend visibility, model-swap recommendations and hard limits, and he calls finishing the Azure migration next year the goal. How spend maps to ROI is left open.","url":"voices.html#v9"},{"t":"voice","title":"GitHub Octoverse 2026","sub":"Simon Willison · simonwillison.net · Oct 28","desc":"Written from the venue, on a free ticket from GitHub's Stars program (he discloses this). Merged PRs tripled in under a year to 220M a month, commits more than tripled to 7.38B a month, and new repos doubled to 30.3M a month. Data-driven Calls the charts a “stark representation of the impact of agentic engineering on GitHub,” and singles out the report's new industry and interoperability breakdowns.","url":"voices.html#v10"},{"t":"voice","title":"New agentic software delivery primitives","sub":"Tim Bozarth · Microsoft · Oct 27","desc":"Plan, build, verify and observe still loop, but agents take on more execution. A shared knowledge layer becomes the new glue between stages. Framework Human judgment concentrates on validation, operation and planning. Memory should be judged by whether it makes agents work better, not by how big it is. (GitHub's parent company, so not fully outside.)","url":"voices.html#v11"},{"t":"voice","title":"GitHub Universe, and the place Conn3x lives","sub":"Conn3x team · conn3x.org · Oct 28","desc":"An open source project's thank-you note written on day one: code, releases and security reports all run on GitHub, with no CLA and no registry account needed. Grateful “The tools are the easy bit.” The community of contributors matters more.","url":"voices.html#v12"},{"t":"link","title":"GitHub Universe Recap - Copilot Dominates","sub":"i-programmer · Kay Ewbank · Oct 29","desc":"a straightforward news recap","url":"https://www.i-programmer.info/news/105-artificial-intelligence/19251-github-universe-recap-copilot-dominates.html"},{"t":"link","title":"How GitHub Plans to Make Coding Easier for Beginners and More Ambitious for Experts","sub":"The AI Economy · Ken Yeung · Oct 28","desc":"largely favorable; notes a crowded model-routing market","url":"https://theaieconomy.substack.com/p/github-copilot-beginners-experts"},{"t":"link","title":"GitHub developers pushed more code in 2026 than in the last two years combined","sub":"The Stack · Yaël Bizouati-Kennedy · Oct 28","desc":"Octoverse numbers; partly paywalled","url":"https://www.thestack.technology/github-developers-pushed-more-code-in-2026-than-in-the-last-two-years-combined/"},{"t":"link","title":"GitHub Universe Details Infrastructure Expansion for Agent-Scale Development","sub":"Visual Studio Magazine · Oct 29","desc":"confirms the capacity figures","url":"https://visualstudiomagazine.com/articles/2026/10/29/github-universe-details-infrastructure-expansion-for-agent-scale-development.aspx"},{"t":"link","title":"GitHub plans to deploy 4 million additional CPU cores to prevent outages","sub":"Techzine · Mels Dees · Oct 29","desc":"based on The Register's coverage","url":"https://www.techzine.eu/news/devops/145378/github-plans-to-deploy-4-million-additional-cpu-cores-to-prevent-outages/"},{"t":"link","title":"The GitHub Copilot app is getting a big update.","sub":"The Verge · Emma Roth · Oct 28","desc":"short item","url":"https://www.theverge.com/ai-artificial-intelligence/1020730/the-github-copilot-app-is-getting-a-big-update"},{"t":"link","title":"Microsoft Copilot Harness Opens to Enterprise Developers: Model Flexibility, Platform Lock-In","sub":"Tech Times · Clayton Lewis · Oct 29","desc":"argues adopters accept Microsoft's routing and pricing","url":"https://www.techtimes.com/articles/329667/20261029/microsoft-copilot-harness-opens-enterprise-developers-model-flexibility-platform-lock.htm"},{"t":"link","title":"Highlights from GitHub Universe 2026","sub":"Microsoft · Lisa Brown Jaloza · Oct 29","desc":"Microsoft's own recap, centered on the developer community","url":"https://commandline.microsoft.com/github-universe-2026-recap/"}];
